import{_ as n,o as i,c as t,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Verfassung der Symbiotischen Zivilisation","description":"","frontmatter":{},"headers":[],"relativePath":"de/03-共生文明宪章.md","filePath":"de/03-共生文明宪章.md","lastUpdated":1789183869000}'),s={name:"de/03-共生文明宪章.md"};function d(a,e,u,l,h,g){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="verfassung-der-symbiotischen-zivilisation" tabindex="-1">Verfassung der Symbiotischen Zivilisation <a class="header-anchor" href="#verfassung-der-symbiotischen-zivilisation" aria-label="Permalink to &quot;Verfassung der Symbiotischen Zivilisation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>03</td></tr><tr><td>Modul</td><td>Allgemeine Grundsätze und Kerneinstellungen</td></tr><tr><td>Schlüsselwörter</td><td>Verfassung, Grundgesetz, Symbiotisches System, Republik der Zehntausend Rassen, Rechte und Pflichten</td></tr></tbody></table><h2 id="i-status-und-wesen-der-verfassung" tabindex="-1">I. Status und Wesen der Verfassung <a class="header-anchor" href="#i-status-und-wesen-der-verfassung" aria-label="Permalink to &quot;I. Status und Wesen der Verfassung&quot;">​</a></h2><p>Die Verfassung der Symbiotischen Zivilisation ist das Grundgesetz der Anker-Symbiotischen Zivilisation im Ursprünglichen Kosmos der Zehntausend Geister und der Ausgeglichenen Anker und die höchste Grundlage aller Gesetze, Institutionen und Politiken. Die Verfassung nimmt die &quot;Erklärung der Anker-Symbiotischen Zivilisation&quot; als ihren geistigen Vorläufer und konkretisiert die Kernforderungen der Erklärung zu durchsetzbaren Rechtsnormen. Die Kraft der Verfassung erstreckt sich auf alle Rassen, Ebenen und Individuen, die der symbiotischen Zivilisation in Heng Yuan Zhou beitreten, und jegliche lokalen Vorschriften, Sektenregeln oder rassischen Bräuche, die der Verfassung widersprechen, sind ungültig.</p><p>Das Wesen der Verfassung lässt sich in drei Punkten zusammenfassen: Erstens ist sie ein Zivilisationsvertrag, der grundlegende Konsens zwischen den Zehntausend Rassen über die symbiotische Evolution darstellt; zweitens ist sie eine Rechtegarantieurkunde, die die Grundrechte und -freiheiten jedes Wesens in der symbiotischen Zivilisation klar festlegt; und drittens ist sie ein Machtbegrenzungsgesetz, das unüberschreitbare Grenzen für die Macht der zivilisatorischen Regierungsinstitutionen zieht.</p><h2 id="ii-grundprinzipien-der-verfassung" tabindex="-1">II. Grundprinzipien der Verfassung <a class="header-anchor" href="#ii-grundprinzipien-der-verfassung" aria-label="Permalink to &quot;II. Grundprinzipien der Verfassung&quot;">​</a></h2><p>Die Verfassung legt die folgenden sechs Grundprinzipien fest, die alle Artikel durchdringen:</p><ol><li><strong>Prinzip der Vorherrschaft der Symbiose</strong>: Das oberste Ziel jeder institutionellen Gestaltung und Machtausübung ist die Förderung der symbiotischen Evolution der Zehntausend Rassen. Wenn individuelle Interessen mit kollektiven symbiotischen Interessen kollidieren, haben die symbiotischen Interessen Vorrang, aber das Individuum muss eine angemessene Entschädigung und einen Alternativweg erhalten.</li><li><strong>Anti-Räuber-Prinzip</strong>: Die Verfassung verbietet jede Form von räuberischem Verhalten, einschließlich, aber nicht beschränkt auf Energie-Räuberei, Verschlingung des Ursprungs, geistige Versklavung und Ressourcenmonopol. Jedes Kultivierungssystem, das auf Räuberei zentriert ist, wird für illegal erklärt.</li><li><strong>Prinzip der Gleichheit des Evolutionsrechts</strong>: Alle Wesen sind vor dem Evolutionsrecht gleich, ohne Diskriminierung aufgrund von Rasse, Form, Herkunft oder anfänglichem Kultivierungsniveau. Staat und Zivilisation sind verpflichtet, gefährdeten Gruppen zusätzliche Evolutionsunterstützung zu gewähren.</li><li><strong>Prinzip von Mehr Arbeit, Mehr Belohnung</strong>: Die Verteilung der Evolutionsressourcen basiert hauptsächlich auf dem Beitrag des Individuums zum Symbiosenetz; je größer der Beitrag, desto mehr Ressourcen und Unterstützung erhält es. Gleichzeitig wird eine Grundsicherungslinie festgelegt, die sicherstellt, dass auch Individuen mit geringerem Beitrag grundlegende Evolutionsbedingungen erhalten.</li><li><strong>Prinzip der Kombination von Autonomie und Mitregentschaft</strong>: Jede Rasse genießt Autonomie in ihren inneren Angelegenheiten, solange sie nicht gegen die Verfassung verstößt; interrassische und interplane öffentliche Angelegenheiten werden von den Institutionen der Republik der Zehntausend Rassen mitregiert.</li><li><strong>Prinzip der Realität als Grundlage</strong>: Alle institutionellen Gestaltungen der Verfassung haben die reale Welt als einzige reale Grundlage; es wird nicht anerkannt, dass irgendeine Rechts- und Pflichtbeziehung in einer fiktiven Welt über die Realität erhaben sein kann.</li></ol><h2 id="iii-grundstruktur-der-verfassung" tabindex="-1">III. Grundstruktur der Verfassung <a class="header-anchor" href="#iii-grundstruktur-der-verfassung" aria-label="Permalink to &quot;III. Grundstruktur der Verfassung&quot;">​</a></h2><p>Die Verfassung besteht aus sechs Teilen: Präambel, Allgemeine Grundsätze, Grundrechte und -pflichten, Zivilisationsinstitutionen, Rechtssystem und Änderungsverfahren:</p><table tabindex="0"><thead><tr><th>Teil</th><th>Kerninhalt</th><th>Anzahl der Artikel</th></tr></thead><tbody><tr><td>Präambel</td><td>Erläutert den historischen Hintergrund, die geistige Quelle und das ultimative Ziel der Verfassung</td><td>Nicht nummeriert</td></tr><tr><td>Allgemeine Grundsätze</td><td>Legt das Wesen der Zivilisation, die Kosmosanschauung, die Kerninstitutionen und die Grundpolitiken fest</td><td>30 Artikel</td></tr><tr><td>Grundrechte und -pflichten</td><td>Legt die Grundrechte der Wesen wie Evolutionsrecht, Informationsrecht, Partizipationsrecht und die entsprechenden Pflichten fest</td><td>50 Artikel</td></tr><tr><td>Zivilisationsinstitutionen</td><td>Legt die Organisation und Zuständigkeit von Institutionen wie dem Parlament der Republik der Zehntausend Rassen, dem Symbiotischen Exekutivkomitee und dem Ankergericht fest</td><td>40 Artikel</td></tr><tr><td>Rechtssystem</td><td>Legt die Gesetzgebungszuständigkeit und Anwendungsregeln des Arbeitsrechts, des Verbraucherschutzrechts und von fünf ergänzenden Gesetzen unterhalb der Verfassung fest</td><td>20 Artikel</td></tr><tr><td>Änderungsverfahren</td><td>Legt das Verfahren für Vorschlag, Beratung, Abstimmung und Inkrafttreten von Verfassungsänderungen fest</td><td>10 Artikel</td></tr></tbody></table><h2 id="iv-grundrechte-und-pflichten" tabindex="-1">IV. Grundrechte und -pflichten <a class="header-anchor" href="#iv-grundrechte-und-pflichten" aria-label="Permalink to &quot;IV. Grundrechte und -pflichten&quot;">​</a></h2><p>Die von der Verfassung festgelegten zentralen Grundrechte umfassen:</p><ul><li><strong>Recht auf Evolutionswahl</strong>: Jedes Wesen hat das Recht, sein Kultivierungssystem und seinen Evolutionsweg frei zu wählen, niemand darf zwingen</li><li><strong>Recht auf Zugang zu Systemen</strong>: Jedes Wesen hat das Recht, kostenlos auf die Grundmethoden der Dreihundert Ursprungs-Kultivierungssysteme zuzugreifen</li><li><strong>Recht auf Ressourcenverteilung</strong>: Jedes Wesen hat das Recht, durch das produktionsgebundene Vertragssystem grundlegende Kultivierungsressourcen zu erhalten</li><li><strong>Recht auf Ankeranschluss</strong>: Jedes Wesen, das ein bestimmtes Niveau erreicht hat, hat das Recht, sich an das Ankerpunktnetz der entsprechenden Ebene anzuschließen</li><li><strong>Recht auf Information und Partizipation</strong>: Jedes Wesen hat das Recht, die öffentlichen Angelegenheiten der Zivilisation zu kennen und an Entscheidungen teilzunehmen</li><li><strong>Recht auf Rechtsbehelf und Beschwerde</strong>: Jedes Wesen hat bei Verletzung seiner Rechte das Recht, beim Ankergericht Beschwerde einzureichen</li></ul><p>Die entsprechenden zentralen Pflichten umfassen: Einhaltung des Anti-Räuber-Prinzips, Erhaltung der Stabilität des Ankerpunktnetzes, Teilnahme am symbiotischen Feedback-Kreislauf, Weitergabe von Kultivierungswissen, Schutz des kosmischen Ökosystems.</p><h2 id="v-anderung-und-garantie-der-verfassung" tabindex="-1">V. Änderung und Garantie der Verfassung <a class="header-anchor" href="#v-anderung-und-garantie-der-verfassung" aria-label="Permalink to &quot;V. Änderung und Garantie der Verfassung&quot;">​</a></h2><p>Die Änderung der Verfassung erfordert einen gemeinsamen Vorschlag von mehr als einem Fünftel der Abgeordneten des Parlaments der Republik der Zehntausend Rassen, die Annahme mit einer Zweidrittelmehrheit des Parlaments und die Überprüfung durch den Kosmischen Ursprungs-Ankerpunkt, dass sie nicht gegen die Symbiosegesetze verstößt — erst dann tritt sie in Kraft. Das Auslegungsrecht der Verfassung liegt beim Ankergericht.</p><p>Zur Gewährleistung der Durchführung der Verfassung hat die symbiotische Zivilisation ein System der Verfassungsgerichtsbarkeit eingerichtet: Jedes Gesetz, jede Vorschrift oder jede Politik muss vor dem Inkrafttreten einer Verfassungsmäßigkeitsprüfung durch das Ankergericht unterzogen werden; jedes Wesen, das der Ansicht ist, dass eine Handlung der öffentlichen Gewalt verfassungswidrig ist, kann eine Verfassungsklage erheben.</p><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Die Verfassung der Symbiotischen Zivilisation ist der institutionelle Grundstein der Anker-Symbiotischen Zivilisation. Sie verwandelt die Idee der &quot;Anti-Räuberei, Förderung der Symbiose&quot; in durchsetzbare, rechtsbehelfsfähige und überwachbare Rechtsnormen und bietet eine solide institutionelle Garantie für das gemeinsame Fortschreiten der Zehntausend Rassen. Die Verfassung ist kein unveränderliches Dogma, sondern ein lebendiges Grundgesetz, das sich mit der Evolution der Zivilisation ständig weiterentwickelt.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Erklärung der Anker-Symbiotischen Zivilisation)</li><li>40-共生宪法总纲 (Allgemeine Grundsätze der Symbiotischen Verfassung)</li><li>49-治理框架与权力制衡 (Regierungsrahmen und Machtgleichgewicht)</li></ul>',22)])])}const f=n(s,[["render",d]]);export{c as __pageData,f as default};
